#!/usr/bin/env bash
# Fetch the unified diff plus the removed-lines supplement.
#
# Env in: GH_TOKEN, GITHUB_REPOSITORY, HEAD_SHA_EVENT, GITHUB_OUTPUT,
#   RUNNER_TEMP, SCRIPT_DIR. Reads muse-vars.env from collect.sh.
# Files out: muse.diff, muse-removed.txt. Output: diff_failed.
# Appends MUSE_DIFF_NOTE / MUSE_REMOVED_NOTE to muse-vars.env.
set -euo pipefail

# shellcheck disable=SC1091  # generated by collect.sh at run time
. "${RUNNER_TEMP}/muse-vars.env"
if [[ "${MUSE_STOP:-1}" == "1" ]]; then exit 0; fi
# shellcheck disable=SC1091  # SCRIPT_DIR is set by the workflow step
. "${SCRIPT_DIR}/lib.sh"

# Unified diff, truncated to a prompt budget. Collection failures are routed
# to the explicit fallback (never reviewed blind). Prefer the complete
# local merge-base diff. --text on that diff: a base/head .gitattributes
# -diff rule would otherwise turn source hunks into "Binary files differ"
# placeholders, hiding removed lines from the supplement below while
# diff_failed stays false. True binaries emit byte noise instead — bounded
# by the caps below and UTF-8-filtered at prompt assembly.
# The compare diff endpoint caps file diffs at 300
# WITHOUT flagging it, so without local history the complete paginated
# inventory decides: over 300 files, hunks would be silently missing and
# the run must fall back instead of reviewing blind.
diff_file="${RUNNER_TEMP}/muse.diff"
if [[ "${MUSE_FILES_FAILED}" == "true" ]]; then
  diff_failed=true
elif [[ "${MUSE_FILES_SOURCE:-}" == "local" && -n "${MUSE_MERGE_BASE:-}" ]] \
  && git -c core.quotePath=false diff --text "${MUSE_MERGE_BASE}" "${HEAD_SHA_EVENT}" \
    > "${diff_file}" 2>"${RUNNER_TEMP}/muse-ghdiff.err"; then
  diff_failed=false
elif (( ${MUSE_TOTAL_FILES:-0} > 300 )); then
  echo "compare diff would silently cap output at 300 files for ${MUSE_TOTAL_FILES} changed files" > "${RUNNER_TEMP}/muse-ghdiff.err"
  diff_failed=true
elif ! gh api -H 'Accept: application/vnd.github.diff' \
  "repos/${GITHUB_REPOSITORY}/compare/${MUSE_BASE_SHA}...${HEAD_SHA_EVENT}" \
  > "${diff_file}" 2>"${RUNNER_TEMP}/muse-ghdiff.err"; then
  diff_failed=true
else
  diff_failed=false
  # GitHub compare diffs silently omit content past 20,000 lines, 1 MB
  # overall, or 500 KB per file: a successful response at those limits
  # can lack deleted tail content in both the diff and the removed-lines
  # supplement (extracted from this file below), yet would otherwise
  # post as a complete review. At any limit, fail closed to the
  # fallback instead — local history (the preferred source above) has
  # no such caps. Thresholds are inclusive: a response exactly at a cap
  # is indistinguishable from a truncated one.
  cmp_lines="$(wc -l < "${diff_file}")"
  cmp_bytes="$(wc -c < "${diff_file}")"
  cmp_maxfile="$(awk '/^diff --git / {if (n > max) max = n; n = 0} {n += length($0) + 1} END {if (n > max) max = n; print max + 0}' "${diff_file}" 2>/dev/null || echo 0)"
  if (( cmp_lines >= 20000 || cmp_bytes >= 1000000 || cmp_maxfile >= 500000 )); then
    echo "compare diff reached a GitHub size limit (lines=${cmp_lines} bytes=${cmp_bytes} max-file-bytes=${cmp_maxfile}); content may be omitted" > "${RUNNER_TEMP}/muse-ghdiff.err"
    diff_failed=true
  fi
  # Binary entries in a compare diff carry no patch content: GitHub
  # documents binary files have no patch, and the diff media type shows
  # only "Binary files ... differ". A deleted/replaced binary (or a text
  # path classified binary via attributes) therefore leaves no base-side
  # evidence in either the diff or the removed-lines supplement derived
  # from it, and the head checkout cannot recover deleted bytes. Fail
  # closed like the size limits above; local history (preferred above,
  # --text) has no such placeholder. Outside hunks only: hunk lines are
  # prefixed, so a source line with this text cannot false-positive.
  if [[ "${diff_failed}" != "true" ]] && grep -q '^Binary files ' "${diff_file}" 2>/dev/null; then
    echo "compare diff contains a binary file with no patch content; base-side evidence is unavailable" > "${RUNNER_TEMP}/muse-ghdiff.err"
    diff_failed=true
  fi
fi
echo "diff_failed=${diff_failed}" >> "${GITHUB_OUTPUT}"

# Removed-lines supplement, extracted from the FULL diff before any
# truncation: beyond the diff cap, deleted base-side lines would be
# invisible — the agent has no shell for `git show`, and checked-out head
# files lack them. Per-file `+++` headers attribute each `-` line; past
# the sidecar byte cap the phase fails closed (below), never partial.
removed_file="${RUNNER_TEMP}/muse-removed.txt"
removed_note=""
if [[ "${diff_failed}" != "true" ]]; then
  # Keep the diff --git and ---/+++ headers: whole-file deletions show
  # +++ /dev/null, so without them removed lines lose their original
  # path. Hunk state first (mirrors ranges.pl): a removed "-- x" line
  # renders as "--- x" and an added "++ y" as "+++ y" INSIDE the hunk,
  # which an unconditional match would mistake for file headers and
  # misattribute every later removal to — while genuinely dropping the
  # removed "-- x" content. Headers only occur outside hunks.
  awk '/^diff --git / {in_hunk=0; print; next} /^@@ / {in_hunk=1; next} !in_hunk && /^--- / {print; next} !in_hunk && /^\+\+\+ / {print; next} in_hunk && /^-/ {print}' \
    "${diff_file}" 2>/dev/null > "${removed_file}" || : > "${removed_file}"
  if (( $(wc -c < "${removed_file}") > 24576 )); then
    # Fail closed like the other evidence caps: this supplement is the
    # ONLY base-side content available to the shell-disabled reviewer,
    # so a byte cut here hides deleted code behind a successful marker.
    # Exiting nonzero fails the Collect step; Post renders the
    # evidence-collection fallback.
    echo "::error::Removed-lines evidence exceeds the 24576-byte supplement cap; failing closed to the fallback review."
    exit 1
  fi
else
  : > "${removed_file}"
fi

budget=60000
diff_note=""
if [[ "${diff_failed}" == "true" ]]; then
  printf '(Diff collection failed; the fallback review explains. Diff error: %s)\n' \
    "$(head -c 300 "${RUNNER_TEMP}/muse-ghdiff.err" 2>/dev/null || true)" > "${diff_file}"
  diff_note=" (collection failed)"
else
  diff_len="$(wc -c < "${diff_file}")"
  if (( diff_len > budget )); then
    head -c "${budget}" "${diff_file}" > "${diff_file}.trunc"
    printf '\n[... PARTIAL DIFF truncated at %s bytes. The tail is NOT visible: read each changed file in full from the working tree, and check the <removed_lines> supplement for deleted base-side lines ...]\n' "${budget}" >> "${diff_file}.trunc"
    mv "${diff_file}.trunc" "${diff_file}"
    diff_note=" (truncated — read full files from the working tree)"
  fi
  if [[ ! -s "${diff_file}" ]]; then
    printf '(No textual diff was returned by the GitHub API.)\n' > "${diff_file}"
  fi
  # No capped-diff note remains: over-300-file runs without local history
  # now fail closed above instead of reviewing a silently cut diff.
fi

{
  printf 'MUSE_DIFF_NOTE=%q\n' "${diff_note}"
  printf 'MUSE_REMOVED_NOTE=%q\n' "${removed_note}"
} >> "${RUNNER_TEMP}/muse-vars.env"
